-- Prepared schema migration only. Apply in a separate reviewed production change.
-- This migration stores verified Cloudinary identities, preserves existing image URLs,
-- and provides transactional project mutations plus a durable post-commit cleanup queue.

ALTER TABLE public.project_images
  ADD COLUMN IF NOT EXISTS cloudinary_public_id text,
  ADD COLUMN IF NOT EXISTS image_provider text NOT NULL DEFAULT 'supabase',
  ADD COLUMN IF NOT EXISTS image_order integer NOT NULL DEFAULT 0;

ALTER TABLE public.projects
  ADD COLUMN IF NOT EXISTS cover_image_public_id text,
  ADD COLUMN IF NOT EXISTS cover_image_provider text NOT NULL DEFAULT 'supabase';

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'project_images_image_provider_check') THEN
    ALTER TABLE public.project_images ADD CONSTRAINT project_images_image_provider_check
      CHECK (image_provider IN ('supabase', 'cloudinary')) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'projects_cover_image_provider_check') THEN
    ALTER TABLE public.projects ADD CONSTRAINT projects_cover_image_provider_check
      CHECK (cover_image_provider IN ('supabase', 'cloudinary')) NOT VALID;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_project_images_cloudinary_public_id
  ON public.project_images (cloudinary_public_id) WHERE cloudinary_public_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_projects_cover_cloudinary_public_id
  ON public.projects (cover_image_public_id) WHERE cover_image_public_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_project_images_project_order
  ON public.project_images (project_id, image_order, id);

WITH ordered AS (
  SELECT id, row_number() OVER (PARTITION BY project_id ORDER BY created_at NULLS LAST, id) - 1 AS image_order
  FROM public.project_images
)
UPDATE public.project_images AS pi SET image_order = ordered.image_order::integer
FROM ordered WHERE pi.id = ordered.id;

