UPDATE public.projects AS p
SET cover_image_public_id = migrated_images.cloudinary_public_id, cover_image_provider = 'cloudinary'
FROM migrated_images
WHERE p.cover_image = migrated_images.image_url
  AND p.cover_image_public_id IS NULL;

CREATE TABLE IF NOT EXISTS public.cloudinary_asset_cleanup_jobs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cloudinary_public_id text NOT NULL,
  secure_url text NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'failed', 'deleted', 'cancelled')) ,
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lease_until timestamptz,
  UNIQUE (cloudinary_public_id)
);
ALTER TABLE public.cloudinary_asset_cleanup_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cloudinary_asset_cleanup_jobs FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cloudinary_asset_cleanup_jobs TO service_role;

-- Keep public project rendering readable while reserving data mutations for the
-- authenticated server routes (which verify the dashboard session before using
-- their service-role Supabase client).
DROP POLICY IF EXISTS "Enable all operations for projects" ON public.projects;
DROP POLICY IF EXISTS "Enable all operations for project_images" ON public.project_images;
DROP POLICY IF EXISTS "Public can read projects" ON public.projects;
DROP POLICY IF EXISTS "Public can read project images" ON public.project_images;
DROP POLICY IF EXISTS "Public can read legacy project images" ON storage.objects;
CREATE POLICY "Public can read projects" ON public.projects
  FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public can read project images" ON public.project_images
  FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS "Allow public access to projects bucket" ON storage.objects;
CREATE POLICY "Public can read legacy project images" ON storage.objects
  FOR SELECT TO anon, authenticated USING (bucket_id = 'projects');
REVOKE INSERT, UPDATE, DELETE ON public.projects FROM PUBLIC, anon, authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.project_images FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.projects, public.project_images TO anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.projects, public.project_images TO service_role;

CREATE OR REPLACE FUNCTION public.cloudinary_queue_cleanup_if_unreferenced(
  p_cloudinary_public_id text,
  p_secure_url text
) RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, auth
AS $$
DECLARE
  v_rows integer;
BEGIN
  IF p_cloudinary_public_id IS NULL OR p_cloudinary_public_id = '' OR p_secure_url IS NULL OR p_secure_url = '' THEN
    RETURN false;
  END IF;

  IF EXISTS (SELECT 1 FROM public.project_images WHERE cloudinary_public_id = p_cloudinary_public_id)
     OR EXISTS (SELECT 1 FROM public.projects WHERE cover_image_public_id = p_cloudinary_public_id) THEN
    RETURN false;
  END IF;

  INSERT INTO public.cloudinary_asset_cleanup_jobs (cloudinary_public_id, secure_url, status, attempts, last_error, lease_until)
  VALUES (p_cloudinary_public_id, p_secure_url, 'pending', 0, NULL, NULL)
  ON CONFLICT (cloudinary_public_id) DO UPDATE
    SET secure_url = EXCLUDED.secure_url,
        status = 'pending',
        attempts = 0,
        last_error = NULL,
        updated_at = now(),
        lease_until = NULL
    WHERE public.cloudinary_asset_cleanup_jobs.status IN ('pending', 'failed', 'deleted', 'cancelled');

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows > 0;
END;
$$;
REVOKE ALL ON FUNCTION public.cloudinary_queue_cleanup_if_unreferenced(text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cloudinary_queue_cleanup_if_unreferenced(text, text) TO service_role;

CREATE OR REPLACE FUNCTION public.cloudinary_save_project(
  p_project_id uuid,
  p_expected_updated_at timestamptz,
  p_project jsonb,
  p_images jsonb
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, auth
AS $$
DECLARE
  v_project public.projects%ROWTYPE;
  v_image public.project_images%ROWTYPE;
  v_descriptor jsonb;
  v_old public.project_images%ROWTYPE;
  v_project_id uuid := p_project_id;
  v_title text;
  v_location text;
  v_description text;
  v_year integer;
  v_featured boolean;
  v_scope jsonb;
  v_scope_type text;
  v_scope_text text[];
  v_new_image_id uuid;
  v_cover_count integer := 0;
  v_total integer;
  v_cover_url text;
  v_cover_public_id text;
  v_cover_provider text;
  v_old_cover_id text;
  v_old_cover_url text;
  v_seen_ids uuid[] := ARRAY[]::uuid[];
  v_cleanup jsonb := '[]'::jsonb;
  v_cleanup_item jsonb;
  v_is_create boolean;
  v_same boolean := true;
  v_job_status text;
  v_enqueued integer := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'server service role required';
  END IF;
  IF p_project_id IS NULL OR jsonb_typeof(p_project) <> 'object' OR jsonb_typeof(p_images) <> 'array' THEN
    RAISE EXCEPTION 'invalid project mutation payload';
  END IF;
  v_total := jsonb_array_length(p_images);
  IF v_total < 1 OR v_total > 20 THEN RAISE EXCEPTION 'project must contain between 1 and 20 images'; END IF;
  SELECT count(*) INTO v_cover_count FROM jsonb_array_elements(p_images) AS item(value)
  WHERE coalesce((item.value->>'is_cover')::boolean, false);
  IF v_cover_count <> 1 THEN RAISE EXCEPTION 'project must have exactly one cover image'; END IF;

  v_title := nullif(btrim(p_project->>'title'), '');
  v_location := nullif(btrim(p_project->>'location'), '');
  v_description := coalesce(p_project->>'description', '');
  v_year := nullif(p_project->>'year', '')::integer;
  v_featured := coalesce((p_project->>'is_featured')::boolean, false);
  v_scope := coalesce(p_project->'scope_of_work', '[]'::jsonb);
  IF v_title IS NULL OR length(v_title) > 255 OR v_location IS NULL OR v_year IS NULL OR
     v_year < 1900 OR v_year > 2200 OR jsonb_typeof(v_scope) <> 'array' THEN
    RAISE EXCEPTION 'invalid project fields';
  END IF;
  SELECT format_type(a.atttypid, a.atttypmod) INTO v_scope_type
  FROM pg_attribute a
  WHERE a.attrelid = 'public.projects'::regclass AND a.attname = 'scope_of_work' AND NOT a.attisdropped;
  IF v_scope_type NOT IN ('text[]', 'jsonb', 'json') THEN
    RAISE EXCEPTION 'unsupported scope_of_work column type: %', coalesce(v_scope_type, 'missing');
  END IF;
  IF v_scope_type = 'text[]' THEN
    SELECT coalesce(array_agg(value), ARRAY[]::text[]) INTO v_scope_text FROM jsonb_array_elements_text(v_scope) AS value;
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = v_project_id FOR UPDATE;
  v_is_create := NOT FOUND;
  IF v_is_create AND p_expected_updated_at IS NOT NULL THEN
    RAISE EXCEPTION 'project no longer exists';
  ELSIF NOT v_is_create AND p_expected_updated_at IS NOT NULL AND v_project.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'project was changed by another edit';
  ELSIF NOT v_is_create AND p_expected_updated_at IS NULL THEN
    -- A create request can be retried with the same client-generated UUID after
    -- a lost response. Accept only an exact replay of the committed payload.
    IF v_project.title IS DISTINCT FROM v_title OR v_project.location IS DISTINCT FROM v_location OR
       v_project.year IS DISTINCT FROM v_year OR v_project.description IS DISTINCT FROM v_description OR
       v_project.is_featured IS DISTINCT FROM v_featured OR to_jsonb(v_project.scope_of_work) IS DISTINCT FROM v_scope THEN
      RAISE EXCEPTION 'project idempotency key is already used by different project data';
    END IF;
    IF (SELECT count(*) FROM public.project_images WHERE project_id = v_project_id) <> v_total THEN
      RAISE EXCEPTION 'project idempotency replay does not match the saved image set';
    END IF;
    FOR v_descriptor IN SELECT value FROM jsonb_array_elements(p_images)
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.project_images pi
        WHERE pi.project_id = v_project_id
          AND pi.image_url = v_descriptor->>'image_url'
          AND pi.cloudinary_public_id = v_descriptor->>'cloudinary_public_id'
          AND pi.is_cover = coalesce((v_descriptor->>'is_cover')::boolean, false)
          AND pi.image_order = (v_descriptor->>'image_order')::integer
      ) THEN
        RAISE EXCEPTION 'project idempotency replay does not match the saved image set';
      END IF;
    END LOOP;
    RETURN jsonb_build_object('project_id', v_project_id, 'replayed', true, 'cleanup_queued', 0);
  END IF;

  IF v_is_create THEN
    IF v_scope_type = 'text[]' THEN
      EXECUTE 'INSERT INTO public.projects (id, title, description, location, year, is_featured, scope_of_work) VALUES ($1, $2, $3, $4, $5, $6, $7)'
        USING v_project_id, v_title, v_description, v_location, v_year, v_featured, v_scope_text;
    ELSIF v_scope_type = 'jsonb' THEN
      EXECUTE 'INSERT INTO public.projects (id, title, description, location, year, is_featured, scope_of_work) VALUES ($1, $2, $3, $4, $5, $6, $7)'
        USING v_project_id, v_title, v_description, v_location, v_year, v_featured, v_scope;
    ELSE
      EXECUTE 'INSERT INTO public.projects (id, title, description, location, year, is_featured, scope_of_work) VALUES ($1, $2, $3, $4, $5, $6, $7)'
        USING v_project_id, v_title, v_description, v_location, v_year, v_featured, v_scope::json;
    END IF;
  ELSE
    v_old_cover_id := v_project.cover_image_public_id;
    v_old_cover_url := v_project.cover_image;
  END IF;

  FOR v_descriptor IN SELECT value FROM jsonb_array_elements(p_images)
  LOOP
    IF coalesce((v_descriptor->>'is_cover')::boolean, false) THEN
      IF v_cover_url IS NOT NULL THEN RAISE EXCEPTION 'duplicate cover image'; END IF;
    END IF;

    IF nullif(v_descriptor->>'id', '') IS NOT NULL THEN
      v_new_image_id := (v_descriptor->>'id')::uuid;
      IF v_new_image_id = ANY(v_seen_ids) THEN RAISE EXCEPTION 'duplicate project image id'; END IF;
      SELECT * INTO v_image FROM public.project_images
      WHERE id = v_new_image_id AND project_id = v_project_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'project image changed or does not belong to this project'; END IF;
      v_seen_ids := array_append(v_seen_ids, v_new_image_id);
      UPDATE public.project_images
      SET is_cover = coalesce((v_descriptor->>'is_cover')::boolean, false),
          image_order = (v_descriptor->>'image_order')::integer
      WHERE id = v_new_image_id;
    ELSE
      IF coalesce(v_descriptor->>'image_provider', '') <> 'cloudinary' OR
         coalesce(v_descriptor->>'cloudinary_public_id', '') !~ ('^projects/' || v_project_id::text || '/[a-f0-9]{64}$') OR
         coalesce(v_descriptor->>'image_url', '') !~ '^https://res\.cloudinary\.com/' OR
         coalesce(v_descriptor->>'image_order', '') !~ '^[0-9]{1,2}$' THEN
        RAISE EXCEPTION 'new project image is missing valid Cloudinary metadata';
      END IF;
      v_job_status := NULL;
      SELECT status INTO v_job_status FROM public.cloudinary_asset_cleanup_jobs
      WHERE cloudinary_public_id = v_descriptor->>'cloudinary_public_id' FOR UPDATE;
      IF v_job_status = 'processing' THEN RAISE EXCEPTION 'image cleanup is in progress; retry after cleanup finishes'; END IF;
      UPDATE public.cloudinary_asset_cleanup_jobs SET status = 'cancelled', updated_at = now(), lease_until = NULL
      WHERE cloudinary_public_id = v_descriptor->>'cloudinary_public_id' AND status IN ('pending', 'failed', 'deleted');
      INSERT INTO public.project_images (project_id, image_url, cloudinary_public_id, image_provider, image_order, is_cover)
      VALUES (v_project_id, v_descriptor->>'image_url', v_descriptor->>'cloudinary_public_id', 'cloudinary',
              (v_descriptor->>'image_order')::integer, coalesce((v_descriptor->>'is_cover')::boolean, false))
      RETURNING * INTO v_image;
      v_new_image_id := v_image.id;
      v_seen_ids := array_append(v_seen_ids, v_new_image_id);
    END IF;

    IF coalesce((v_descriptor->>'is_cover')::boolean, false) THEN
      v_cover_url := v_image.image_url;
      v_cover_public_id := v_image.cloudinary_public_id;
      v_cover_provider := v_image.image_provider;
    END IF;
  END LOOP;

  FOR v_old IN SELECT * FROM public.project_images WHERE project_id = v_project_id AND NOT (id = ANY(v_seen_ids)) FOR UPDATE
  LOOP
    IF v_old.cloudinary_public_id IS NOT NULL THEN
      v_cleanup := v_cleanup || jsonb_build_array(jsonb_build_object('public_id', v_old.cloudinary_public_id, 'secure_url', v_old.image_url));
    END IF;
  END LOOP;
  DELETE FROM public.project_images WHERE project_id = v_project_id AND NOT (id = ANY(v_seen_ids));

  UPDATE public.projects
  SET title = v_title, description = v_description, location = v_location, year = v_year,
      is_featured = v_featured,
      cover_image = v_cover_url, cover_image_public_id = v_cover_public_id, cover_image_provider = v_cover_provider
  WHERE id = v_project_id;

  IF v_scope_type = 'text[]' THEN
    EXECUTE 'UPDATE public.projects SET scope_of_work = $1 WHERE id = $2' USING v_scope_text, v_project_id;
  ELSIF v_scope_type = 'jsonb' THEN
    EXECUTE 'UPDATE public.projects SET scope_of_work = $1 WHERE id = $2' USING v_scope, v_project_id;
  ELSIF v_scope_type = 'json' THEN
    EXECUTE 'UPDATE public.projects SET scope_of_work = $1 WHERE id = $2' USING v_scope::json, v_project_id;
  ELSE
    RAISE EXCEPTION 'unsupported scope_of_work column type: %', coalesce(v_scope_type, 'missing');
  END IF;

  IF v_old_cover_id IS NOT NULL AND v_old_cover_id IS DISTINCT FROM v_cover_public_id THEN
    v_cleanup := v_cleanup || jsonb_build_array(jsonb_build_object('public_id', v_old_cover_id, 'secure_url', v_old_cover_url));
  END IF;
  FOR v_cleanup_item IN SELECT value FROM jsonb_array_elements(v_cleanup)
  LOOP
    IF public.cloudinary_queue_cleanup_if_unreferenced(v_cleanup_item->>'public_id', v_cleanup_item->>'secure_url') THEN
      v_enqueued := v_enqueued + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('project_id', v_project_id, 'replayed', false, 'cleanup_queued', v_enqueued);
END;
$$;
REVOKE ALL ON FUNCTION public.cloudinary_save_project(uuid, timestamptz, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cloudinary_save_project(uuid, timestamptz, jsonb, jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.cloudinary_delete_project(p_project_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, auth
AS $$
DECLARE
  v_project public.projects%ROWTYPE;
  v_image public.project_images%ROWTYPE;
  v_assets jsonb := '[]'::jsonb;
  v_item jsonb;
  v_queued integer := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'server service role required'; END IF;
  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('deleted', false, 'cleanup_queued', 0); END IF;
  FOR v_image IN SELECT * FROM public.project_images WHERE project_id = p_project_id FOR UPDATE
  LOOP
    IF v_image.cloudinary_public_id IS NOT NULL THEN
      v_assets := v_assets || jsonb_build_array(jsonb_build_object('public_id', v_image.cloudinary_public_id, 'secure_url', v_image.image_url));
    END IF;
  END LOOP;
  IF v_project.cover_image_public_id IS NOT NULL THEN
    v_assets := v_assets || jsonb_build_array(jsonb_build_object('public_id', v_project.cover_image_public_id, 'secure_url', v_project.cover_image));
  END IF;
  DELETE FROM public.projects WHERE id = p_project_id;
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_assets)
  LOOP
    IF public.cloudinary_queue_cleanup_if_unreferenced(v_item->>'public_id', v_item->>'secure_url') THEN v_queued := v_queued + 1; END IF;
  END LOOP;
  RETURN jsonb_build_object('deleted', true, 'cleanup_queued', v_queued);
END;
$$;
REVOKE ALL ON FUNCTION public.cloudinary_delete_project(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cloudinary_delete_project(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.cloudinary_enqueue_orphan_assets(p_assets jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, auth
AS $$
DECLARE
  v_item jsonb;
  v_queued integer := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' OR jsonb_typeof(p_assets) <> 'array' THEN
    RAISE EXCEPTION 'server service role and asset list required';
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_assets)
  LOOP
    IF coalesce(v_item->>'public_id', '') !~ '^(projects/[0-9a-f-]{36}/[a-f0-9]{64}|supabase-projects/[a-zA-Z0-9_-]+)$' OR
       coalesce(v_item->>'secure_url', '') !~ '^https://res\.cloudinary\.com/' THEN
      RAISE EXCEPTION 'invalid Cloudinary orphan identity';
    END IF;
    IF public.cloudinary_queue_cleanup_if_unreferenced(v_item->>'public_id', v_item->>'secure_url') THEN
      v_queued := v_queued + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('cleanup_queued', v_queued);
END;
$$;
REVOKE ALL ON FUNCTION public.cloudinary_enqueue_orphan_assets(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cloudinary_enqueue_orphan_assets(jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.cloudinary_claim_asset_cleanup_jobs(p_limit integer DEFAULT 20)
RETURNS SETOF public.cloudinary_asset_cleanup_jobs
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, auth
AS $$
DECLARE
  v_job public.cloudinary_asset_cleanup_jobs%ROWTYPE;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'server service role required'; END IF;
  IF p_limit < 1 OR p_limit > 50 THEN RAISE EXCEPTION 'cleanup limit must be between 1 and 50'; END IF;
  FOR v_job IN
    SELECT * FROM public.cloudinary_asset_cleanup_jobs
    WHERE status IN ('pending', 'failed') OR (status = 'processing' AND lease_until < now())
    ORDER BY created_at LIMIT p_limit FOR UPDATE SKIP LOCKED
  LOOP
    IF EXISTS (SELECT 1 FROM public.project_images WHERE cloudinary_public_id = v_job.cloudinary_public_id)
       OR EXISTS (SELECT 1 FROM public.projects WHERE cover_image_public_id = v_job.cloudinary_public_id) THEN
      UPDATE public.cloudinary_asset_cleanup_jobs
      SET status = 'cancelled', updated_at = now(), lease_until = NULL,
          last_error = 'asset is still referenced by a project'
      WHERE id = v_job.id;
      CONTINUE;
    END IF;
    UPDATE public.cloudinary_asset_cleanup_jobs
    SET status = 'processing', attempts = attempts + 1, updated_at = now(), lease_until = now() + interval '5 minutes'
    WHERE id = v_job.id
    RETURNING * INTO v_job;
    RETURN NEXT v_job;
  END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.cloudinary_claim_asset_cleanup_jobs(integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cloudinary_claim_asset_cleanup_jobs(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.cloudinary_finish_asset_cleanup(
  p_job_id uuid,
  p_success boolean,
  p_error text DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, auth
AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'server service role required'; END IF;
  UPDATE public.cloudinary_asset_cleanup_jobs
  SET status = CASE WHEN p_success THEN 'deleted' ELSE 'failed' END,
      last_error = CASE WHEN p_success THEN NULL ELSE left(coalesce(p_error, 'Cloudinary deletion failed'), 1000) END,
      updated_at = now(), lease_until = NULL
  WHERE id = p_job_id AND status = 'processing';
  IF NOT FOUND THEN RAISE EXCEPTION 'cleanup job is not claimed'; END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.cloudinary_finish_asset_cleanup(uuid, boolean, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cloudinary_finish_asset_cleanup(uuid, boolean, text) TO service_role;

